import { createRequire } from "node:module";
import * as path from "node:path";
import { getNativeModuleCandidates } from "./native-module-path.js";

const load = createRequire(import.meta.url);
const helpers = new Map();

function loadHelper(platform, suffix = "") {
  const arch = process.arch;
  if (arch !== "x64" && arch !== "arm64") return undefined;
  const nativePath = path.join("native", platform, "prebuilds", `${platform}-${arch}`, `${platform}-helper${suffix}.node`);
  if (helpers.has(nativePath)) return helpers.get(nativePath);
  for (const modulePath of getNativeModuleCandidates(nativePath)) {
    try {
      const helper = load(modulePath);
      if (typeof helper?.getText === "function") {
        helpers.set(nativePath, helper);
        return helper;
      }
    } catch {
      // Try the next location.
    }
  }
  helpers.set(nativePath, undefined);
  return undefined;
}

function getPlatformHelper() {
  if (process.platform !== "darwin" && process.platform !== "win32") return undefined;
  return loadHelper(process.platform);
}

// The clipboard helper opens the X display, so it loads only when one is set.
export function getNativeClipboard() {
  if (process.platform !== "linux") return getPlatformHelper();
  if (!process.env.DISPLAY) return undefined;
  return loadHelper("linux", "-x11");
}

export function isNativeModifierPressed(key) {
  const helper = getPlatformHelper();
  if (!helper?.isModifierPressed) return false;
  try {
    return helper.isModifierPressed(key) === true;
  } catch {
    return false;
  }
}
